def get_path_value(ctx, path_str):
    parts = path_str.split('.')
    curr = ctx
    for p in parts:
        if isinstance(curr, dict) and p in curr:
            curr = curr[p]
        else:
            return None
    return curr

def evaluate_policy(rule, context):
    # Base cases: primitives
    if not isinstance(rule, dict):
        return rule

    # Variable reference
    if "var" in rule:
        return get_path_value(context, rule["var"])

    # Operators
    if "and" in rule:
        return all(bool(evaluate_policy(sub, context)) for sub in rule["and"])
    if "or" in rule:
        return any(bool(evaluate_policy(sub, context)) for sub in rule["or"])
    if "not" in rule:
        return not bool(evaluate_policy(rule["not"], context))
    if "eq" in rule:
        left = evaluate_policy(rule["eq"][0], context)
        right = evaluate_policy(rule["eq"][1], context)
        return left == right
    if "in" in rule:
        needle = evaluate_policy(rule["in"][0], context)
        haystack = evaluate_policy(rule["in"][1], context)
        return needle in haystack if haystack is not None else False
    if "gte" in rule:
        left = evaluate_policy(rule["gte"][0], context)
        right = evaluate_policy(rule["gte"][1], context)
        if left is None or right is None:
            return False
        return left >= right

    return False

tests.code:
ctx = {"user": {"role": "admin", "department": "finance"}}
rule = {"eq": [{"var": "user.role"}, "admin"]}
assert evaluate_policy(rule, ctx) is True

rule2 = {"eq": [{"var": "user.role"}, "editor"]}
assert evaluate_policy(rule2, ctx) is False

ctx = {
    "user": {"role": "manager", "clearance": 3},
    "resource": {"min_clearance": 2, "owner": "bob"}
}
# (role == 'admin') OR (clearance >= min_clearance)
policy = {
    "or": [
        {"eq": [{"var": "user.role"}, "admin"]},
        {"gte": [{"var": "user.clearance"}, {"var": "resource.min_clearance"}]}
    ]
}
assert evaluate_policy(policy, ctx) is True

ctx = {"user": {"country": "CA"}, "allowed_countries": ["US", "CA", "MX"]}
policy = {
    "and": [
        {"in": [{"var": "user.country"}, {"var": "allowed_countries"}]},
        {"not": {"eq": [{"var": "user.country"}, "CU"]}}
    ]
}
assert evaluate_policy(policy, ctx) is True

ctx_blocked = {"user": {"country": "GB"}, "allowed_countries": ["US", "CA", "MX"]}
assert evaluate_policy(policy, ctx_blocked) is False

ctx = {}
policy = {"eq": [{"var": "user.profile.age"}, 25]}
assert evaluate_policy(policy, ctx) is False
